@Override
	public ItemStack onItemRightClick(ItemStack stack, World world, EntityPlayer player) {
		boolean makeshift = stack.getItemDamage() == 1;

		List<ItemStack> stacks = new ArrayList();

		for(ItemStack inv : player.inventory.mainInventory) {
			if(inv != null && inv.getItem() instanceof ItemGunBaseNT) {
				ItemGunBaseNT gun = (ItemGunBaseNT) inv.getItem();
				if(gun.defaultAmmo != null && !(makeshift && gun.isDefaultExpensive)) stacks.add(inv);
			}
		}

		if(stacks.size() <= 0) return stack;

		Collections.shuffle(stacks);

		int maxGunCount = 3;

		for(int i = 0; i < maxGunCount && i < stacks.size(); i++) {
			ItemStack gunStack = stacks.get(i);
			ItemGunBaseNT gun = (ItemGunBaseNT) gunStack.getItem();
			ItemStack ammo = gun.defaultAmmo.copy();
			if(makeshift) ammo.stackSize = (int) Math.ceil(ammo.stackSize / 2D);
			ItemStack remainder = InventoryUtil.tryAddItemToInventory(player.inventory.mainInventory, ammo);
			if(remainder != null && remainder.stackSize > 0) player.dropPlayerItemWithRandomChoice(remainder, false);
		}

		world.playSoundAtEntity(player, "hbm:item.unpack", 1.0F, 1.0F);
		player.inventoryContainer.detectAndSendChanges();
		stack.stackSize--;

		return stack;
	}

@Override
	public ItemStack onItemRightClick(ItemStack stack, World world, EntityPlayer player) {

		if(player.isSneaking() || world.isRemote) {
			return stack;
		}

		if(!stack.hasTagCompound()) {
			world.playSoundAtEntity(player, "random.orb", 0.25F, 0.75F);
			return stack;
		}

		if(this.getCharge(stack) < 10_000) {
			world.playSoundAtEntity(player, "random.orb", 0.25F, 0.75F);
			return stack;
		}

		int x = stack.getTagCompound().getInteger("x");
		int y = stack.getTagCompound().getInteger("y");
		int z = stack.getTagCompound().getInteger("z");

		world.getChunkProvider().loadChunk(x >> 4, z >> 4);

		if(com.hbm.world.WorldBlockState.read(world, x, y, z).getBlock() == ModBlocks.teleanchor) {

			if(player.isRiding()) {
				player.mountEntity(null);
			}

			world.newExplosion(player, x + 0.5, y + 1 + player.height / 2, z + 0.5, 2F, false, false);
			world.playSoundEffect(player.posX, player.posY, player.posZ, "mob.endermen.portal", 1.0F, 1.0F);
			player.setPositionAndUpdate(x + 0.5, y + 1, z + 0.5);
			//world.playSoundEffect(player.posX, player.posY, player.posZ, "mob.endermen.portal", 1.0F, 1.0F);
			player.fallDistance = 0.0F;

			for(int i = 0; i < 32; ++i) {
				world.spawnParticle("portal", player.posX, player.posY + player.getRNG().nextDouble() * 2.0D, player.posZ, player.getRNG().nextGaussian(), 0.0D, player.getRNG().nextGaussian());
			}

			this.dischargeBattery(stack, 10_000);

		} else {
			world.playSoundAtEntity(player, "random.orb", 0.25F, 0.75F);
		}

		return stack;
	}

