@Override
	public boolean onItemUse(ItemStack stack, EntityPlayer player, World world, int x, int y, int z, int side, float fX, float fY, float fZ) {

		Block b = com.hbm.world.WorldBlockState.read(world, x, y, z).getBlock();

		if(b instanceof IToolable && ((IToolable)b).onScrew(world, player, x, y, z, side, fX, fY, fZ, ToolType.BOLT)) {

			if(!world.isRemote) {

				world.playSoundAtEntity(player, "hbm:item.boltgun", 1.0F, 1.0F);
				player.inventoryContainer.detectAndSendChanges();
				ForgeDirection dir = ForgeDirection.getOrientation(side);
				double off = 0.25;

				NBTTagCompound data = new NBTTagCompound();
				data.setString("type", "vanillaExt");
				data.setString("mode", "largeexplode");
				data.setFloat("size", 1F);
				data.setByte("count", (byte)1);
				PacketThreading.createAllAroundThreadedPacket(new AuxParticlePacketNT(data, x + fX + dir.offsetX * off, y + fY + dir.offsetY * off, z + fZ + dir.offsetZ * off), new TargetPoint(world.provider.getDimension(), x, y, z, 50));

				playAnimation(player, ToolAnimation.SWING);
			}

			return false;
		}

		return false;
	}

@Override
	public ItemStack onItemRightClick(ItemStack stack, World world, EntityPlayer player)
	{
		RayTraceResult pos = Library.rayTrace(player, 500, 1);
		int x = pos.getBlockPos().getX();
		int y = pos.getBlockPos().getY();
		int z = pos.getBlockPos().getZ();
		
		boolean b = false;
		boolean b2 = false;
		
	    if(!world.isRemote)
		{
			EntityBomber bomber;
			switch(stack.getItemDamage()) {

				case 1: bomber = EntityBomber.statFacNapalm(world, x, y, z); break;
				case 2: bomber = EntityBomber.statFacChlorine(world, x, y, z); break;
				case 3: bomber = EntityBomber.statFacOrange(world, x, y, z); break;
				case 4: bomber = EntityBomber.statFacABomb(world, x, y, z); break;
				case 5: bomber = EntityBomber.statFacStinger(world, x, y, z); break;
				case 6: bomber = EntityBomber.statFacBoxcar(world, x, y, z); break;
				case 7: bomber = EntityBomber.statFacPC(world, x, y, z); break;
				case 8: bomber = EntityBomber.statFacCV(world, x, y, z);
				b2 = true; break;
				default: bomber = EntityBomber.statFacCarpet(world, x, y, z);

			}
			WorldUtil.loadAndSpawnEntityInWorld(bomber);
			player.sendMessage(new TextComponentString("Called in airstrike!"));
			world.playSoundAtEntity(player, "hbm:item.techBleep", 1.0F, 1.0F);

			if(b2){
				player.sendMessage(new TextComponentString("Rerouted Civilian Traffic!"));
		        world.playSoundAtEntity(player, "hbm:item.techBleep", 1.0F, 1.0F);
			}

		}

		stack.stackSize -= 1;

		return stack;
	}

