private ItemStack installFilterOn(ItemStack helmet, ItemStack filter, World world, EntityPlayer player) {

		if(!(helmet.getItem() instanceof IGasMask)) {
			return filter;
		}

		IGasMask mask = (IGasMask) helmet.getItem();
		if(!mask.isFilterApplicable(helmet, player, filter))
			return filter;

		ItemStack copy = filter.copy();
		ItemStack current = ArmorUtil.getGasMaskFilter(helmet);

		if(current != null) {
			filter = current;
		} else {
			filter.stackSize = 0;
		}

		ArmorUtil.installGasMaskFilter(helmet, copy);

		world.playSoundAtEntity(player, "hbm:item.gasmaskScrew", 1.0F, 1.0F);

		return filter;
	}

@Override
	public ItemStack onItemRightClick(ItemStack stack, World world, EntityPlayer player) {

		if(ArmorFSB.hasFSBArmorIgnoreCharge(player) && player.inventory.armorInventory[2].getItem() instanceof ArmorFSBPowered) {

			for(ItemStack st : player.inventory.armorInventory) {

				if(st == null)
					continue;

				if(st.getItem() instanceof IBatteryItem) {

					long maxcharge = ((IBatteryItem) st.getItem()).getMaxCharge(st);
					long charge = ((IBatteryItem) st.getItem()).getCharge(st);
					long newcharge = Math.min(charge + this.charge, maxcharge);

					((IBatteryItem) st.getItem()).setCharge(st, newcharge);
				}
			}

			stack.stackSize--;

			world.playSoundAtEntity(player, "hbm:item.battery", 1.0F, 1.0F);
		}

		return stack;
	}

