public net.minecraft.network.Packet<?> getPacketFrom(IMessage message) {
		PacketThreading.lock.lock();
		try {
			return serverChannel.generatePacketFrom(message);
		} finally {
			PacketThreading.lock.unlock();
		}
	}

public net.minecraft.network.Packet<?> getPacketFrom(IMessage message) {
